                    }
                } elseif ($tokens[$index]->isGivenKind(T_DOUBLE_COLON)) {
                    $prevNameIndex = $index;
                    $typeStartIndex = null;
                    $typeEndIndex = null;

                    while (true) {
                        $prevNameIndex = $tokens->getPrevMeaningfulToken($prevNameIndex);
                        if ($tokens[$prevNameIndex]->isObjectOperator()) {
                            break;
                        }

                        if ($tokens[$prevNameIndex]->equalsAny([[T_STRING], [T_NS_SEPARATOR]])) {
                            $typeStartIndex = $prevNameIndex;
                            if (null === $typeEndIndex) {
                                $typeEndIndex = $prevNameIndex;
                            }
                        } else {
                            if (null !== $typeEndIndex) {
                                $prevNameIndex += $this->shortenClassIfPossible($tokens, $typeStartIndex, $typeEndIndex, $uses, $namespaceName);
                            }

                            break;
                        }
                    }
                } elseif ($tokens[$index]->isGivenKind(T_VARIABLE)) {
                    $prevIndex = $tokens->getPrevMeaningfulToken($index);
                    if (null !== $prevIndex && $tokens[$prevIndex]->isGivenKind(T_STRING)) {
