                        while ($tokens[$attributeNameIndex]->equalsAny([[T_STRING], [T_NS_SEPARATOR]])) {
                            $attributeNameIndex = $tokens->getPrevMeaningfulToken($attributeNameIndex);
                        }

                        $typeStartIndex = null;
                        $typeEndIndex = null;
                        $attributeScanIndex = $attributeNameIndex;
                        while (true) {
                            $attributeScanIndex = $tokens->getNextMeaningfulToken($attributeScanIndex);

                            if ($tokens[$attributeScanIndex]->equalsAny([[T_STRING], [T_NS_SEPARATOR]])) {
                                if (null === $typeStartIndex) {
                                    $typeStartIndex = $attributeScanIndex;
                                }
                                $typeEndIndex = $attributeScanIndex;
                            } else {
                                if (null !== $typeStartIndex) {
                                    $attributeScanIndex += $this->shortenClassIfPossible($tokens, $typeStartIndex, $typeEndIndex, $uses, $namespaceName);
                                }

                                break;
                            }
                        }
                    }
